SELECT t.id, t.work_order_id, t.flow_id, t.node_id, t.node_order,
       t.approver_id, t.status, t.round, t.add_sign, t.comment,
       t.create_time, t.update_time
FROM work_order_task t
WHERE t.work_order_id = #{orderId}
  AND t.approver_id = #{approverId}
  AND t.round = #{round}
  AND t.status = 0
ORDER BY t.node_order DESC, t.id DESC
LIMIT 1

SELECT t.id, t.work_order_id, t.flow_id, t.node_id, t.node_order,
       t.approver_id, t.status, t.round, t.add_sign, t.comment,
       t.create_time, t.update_time
FROM work_order_task t
WHERE t.work_order_id = #{orderId}
  AND t.round = #{round}
  AND t.node_id = #{nodeId}
  AND t.status = 0
ORDER BY t.id ASC

SELECT COUNT(*)
FROM work_order_task
WHERE work_order_id = #{orderId}
  AND round = #{round}
  AND node_id = #{nodeId}
  AND status = 0

SELECT COUNT(*)
FROM work_order_task
WHERE work_order_id = #{orderId}
  AND round = #{round}
  AND node_id = #{nodeId}
  AND add_sign = 1

SELECT COUNT(*)
FROM work_order_task
WHERE work_order_id = #{orderId}
  AND approver_id = #{approverId}

